#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Адрес и размер дисплея: 0x27 — самый частый адрес, 16 колонок, 2 строки
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  // Инициализация дисплея
  lcd.init();
  lcd.backlight();  // Включаем подсветку

  // Выводим текст "6754323" на первую строку (нумерация с 0)
  lcd.setCursor(0, 0);
  lcd.print("6754323");
}

void loop() {
  // В этом примере ничего не меняется, текст остаётся на экране
}
